package cu.shalev.designsystem.ilustracion

import androidx.compose.foundation.Image
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import cu.shalev.designsystem.theme.ShalevTheme

/**
 * P24: nueve ilustraciones de estados vacíos, sin resultados y error; P29 añade Servicios (`services.svg`).
 *
 * Origen: unDraw (https://undraw.co), licencia unDraw: uso libre, también comercial, sin atribución obligatoria.
 * Las diez se recopilaron del paquete npm `undraw-svg` 2.0.0 (MIT). Se convierten con `undraw2kt.py`
 * (formas → trazados, transformaciones aplicadas, 1 decimal) y viajan dentro del APK: no se descarga nada.
 *
 * Color:
 * - el acento de unDraw toma el `primary` del tema;
 * - en oscuro, los grises neutros se invierten para que las figuras se vean sobre fondo oscuro;
 * - los tonos de piel y los colores saturados no cambian.
 * Son decorativas: TalkBack no las lee (el título y el detalle del estado vacío ya lo dicen).
 */
enum class ShalevIlustracion { Error, SinResultados, Inventario, Elaboracion, Carrito, Registros, Precios, SinTurno, NoExiste, Servicios }

/** Ilustración decorativa del estado vacío, ajustada a [ancho] y con la proporción del original. */
@Composable
fun ShalevIlustracionImagen(tipo: ShalevIlustracion, modifier: Modifier = Modifier, ancho: Dp = 180.dp) {
    val primary = MaterialTheme.colorScheme.primary
    val oscuro = ShalevTheme.colors.isDark
    val vector = remember(tipo, primary, oscuro) { construir(tipo, primary, oscuro, ancho) }
    Image(vector, contentDescription = null, modifier = modifier)
}

/** Un trazado: datos SVG, color en claro y en oscuro (0 = primary del tema) y opacidad. */
private class Trazo(val d: String, val claro: Long, val oscuro: Long, val alpha: Float)

private class Dibujo(val ancho: Float, val alto: Float, val trazos: List<Trazo>)

internal fun construir(tipo: ShalevIlustracion, primary: Color, oscuro: Boolean, ancho: Dp): ImageVector {
    val dibujo = datos(tipo)
    return ImageVector.Builder(
        name = tipo.name, defaultWidth = ancho, defaultHeight = ancho * (dibujo.alto / dibujo.ancho),
        viewportWidth = dibujo.ancho, viewportHeight = dibujo.alto,
    ).apply {
        dibujo.trazos.forEach { t ->
            val c = if (oscuro) t.oscuro else t.claro
            addPath(pathData = addPathNodes(t.d), fill = SolidColor(if (c == 0L) primary else Color(c)), fillAlpha = t.alpha)
        }
    }.build()
}

/** Nº de trazados de cada ilustración (lo comprueba un test JVM). */
internal fun trazos(tipo: ShalevIlustracion): Int = datos(tipo).trazos.size

private fun datos(tipo: ShalevIlustracion): Dibujo = when (tipo) {
    ShalevIlustracion.Error -> error()
    ShalevIlustracion.SinResultados -> sinresultados()
    ShalevIlustracion.Inventario -> inventario()
    ShalevIlustracion.Elaboracion -> elaboracion()
    ShalevIlustracion.Carrito -> carrito()
    ShalevIlustracion.Registros -> registros()
    ShalevIlustracion.Precios -> precios()
    ShalevIlustracion.SinTurno -> sinturno()
    ShalevIlustracion.NoExiste -> noexiste()
    ShalevIlustracion.Servicios -> servicios()
}

